style.css:
/* Sugar & Espresso — Spotify */
/* i really want this to be global */
/* color palette */
:root {
  --my-pink: #f6e3e8;
  --my-blush: #edc4cf;
  --my-rose: #d99aaa;
  --my-brown: #593b35;
  --my-espresso: #38241f;
  --my-cream: #fff9f6;
}

/* main background */
body,
#main,
[data-testid="main-view-container"] {
  background: var(--my-pink) !important;
  color: var(--my-brown) !important;
}

/* sidebars */
[data-testid="left-sidebar"],
[data-testid="right-sidebar"] {
  background: var(--my-cream) !important;
  border-radius: 20px !important;
  border: 1px solid var(--my-blush) !important;
}

/* playlist cards */
[data-testid="card"],
[data-testid="playlist-card"] {
  background: var(--my-cream) !important;
  border: 1px solid var(--my-blush) !important;
  border-radius: 18px !important;
  position: relative !important;
  overflow: visible !important;
}

/* tiny decorative bows */
[data-testid="card"]::after,
[data-testid="playlist-card"]::after {
  content: "୨୧" !important;
  position: absolute !important;
  top: 7px !important;
  right: 10px !important;
  color: var(--my-rose) !important;
  font-size: 19px !important;
  pointer-events: none !important;
  z-index: 5 !important;
}

/* sidebar ribbon details */
[data-testid="left-sidebar"]::after {
  content: "♡ ୨୧ ♡" !important;
  display: block !important;
  text-align: center !important;
  color: var(--my-rose) !important;
  padding: 12px !important;
  letter-spacing: 5px !important;
}

/* typography */
h1, h2, h3 {
  color: var(--my-espresso) !important;
}

/* playback bar */
[data-testid="now-playing-bar"] {
  background: var(--my-espresso) !important;
  color: var(--my-cream) !important;
  border-top: 2px solid var(--my-rose) !important;
}

/* album artwork */
img {
  border-radius: 14px !important;
}

/* progress */
input[type="range"] {
  accent-color: var(--my-rose) !important;
}

/* selection */
::selection {
  background: var(--my-rose) !important;
  color: white !important;
}

/* scrollbar */
::-webkit-scrollbar-thumb {
  background: var(--my-rose) !important;
  border-radius: 20px !important;
}
